<?php require_once 'includes/functions.php';$u=login_required();$s=db()->prepare('SELECT * FROM users WHERE user_id=?');$s->execute([$u['user_id']]);$p=$s->fetch();$dp=null;if($u['role']==='donor'){$s=db()->prepare('SELECT * FROM donor_profiles WHERE user_id=?');$s->execute([$u['user_id']]);$dp=$s->fetch();}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$loc=trim($_POST['location']??'');$bg=$_POST['blood_group']??'';if(!$name||!$loc||!in_array($bg,['A+','A-','B+','B-','AB+','AB-','O+','O-']))$err='Please complete the required fields.';else{db()->prepare('UPDATE users SET name=?,phone=?,location=?,blood_group=? WHERE user_id=?')->execute([$name,$phone,$loc,$bg,$u['user_id']]);if($dp){$av=$_POST['availability']??'Available';$eligible=isset($_POST['eligible'])?1:0;if(!in_array($av,['Available','Unavailable']))$av='Unavailable';db()->prepare('UPDATE donor_profiles SET availability=?,eligible=? WHERE user_id=?')->execute([$av,$eligible,$u['user_id']]);}$u['name']=$name;$u['location']=$loc;$u['blood_group']=$bg;$_SESSION['user']=$u;flash('Profile updated.');go('profile.php');}}$title='Profile';require 'includes/header.php';?><section class="form"><h1>Profile and availability</h1><?php if($err):?><p class="alert error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Name<input name="name" value="<?=e($p['name'])?>" required></label><label>Email<input disabled value="<?=e($p['email'])?>"></label><label>Phone<input name="phone" value="<?=e($p['phone'])?>"></label><label>Blood group<select name="blood_group"><?php foreach(['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $b):?><option <?= $p['blood_group']===$b?'selected':''?>><?=e($b)?></option><?php endforeach;?></select></label><label>Location<input name="location" value="<?=e($p['location'])?>" required></label><?php if($dp):?><label>Availability<select name="availability"><option <?= $dp['availability']==='Available'?'selected':''?>>Available</option><option <?= $dp['availability']==='Unavailable'?'selected':''?>>Unavailable</option></select></label><label><input type="checkbox" name="eligible" value="1" <?=$dp['eligible']?'checked':''?>> Self-reported eligible to donate</label><p>Last donation: <?=e($dp['last_donation']??'Not recorded')?></p><?php endif;?><button class="btn">Save profile</button></form></section><?php require 'includes/footer.php';?>